23	function freeSlotsForDay(roomId: string, day: Slot): Slot[] {
24	  const dayStart = Date.parse(day.startsAt);
25	  const dayEnd = Date.parse(day.endsAt);
26	  const busy = bookingsForRoom(roomId)
27	    .filter((booking) => overlaps(day.startsAt, day.endsAt, booking.startsAt, booking.endsAt))
28	    .map((booking) => ({
29	      start: Math.max(Date.parse(booking.startsAt), dayStart),
30	      end: Math.min(Date.parse(booking.endsAt), dayEnd)
31	    }))
32	    .sort((a, b) => a.start - b.start);
33	
34	  const merged = busy.reduce<{ start: number; end: number }[]>((slots, slot) => {
35	    const previous = slots.at(-1);
36	    if (!previous || slot.start > previous.end) {
37	      slots.push(slot);
38	    } else {
39	      previous.end = Math.max(previous.end, slot.end);
40	    }
41	    return slots;
42	  }, []);
43	
44	  const free: Slot[] = [];
45	  let cursor = dayStart;
46	  for (const slot of merged) {
47	    if (cursor < slot.start) {
48	      free.push({ startsAt: new Date(cursor).toISOString(), endsAt: new Date(slot.start).toISOString() });
49	    }
50	    cursor = Math.max(cursor, slot.end);
51	  }
52	  if (cursor < dayEnd) {
53	    free.push({ startsAt: new Date(cursor).toISOString(), endsAt: new Date(dayEnd).toISOString() });
54	  }
55	  return free;
56	}
