 8	export function requireString(payload: Record<string, unknown>, field: string): string {
 9	  const value = payload[field];
10	  if (typeof value !== "string" || value.trim() === "") {
11	    throw new ValidationError(`champ manquant ou vide : ${field}`);
12	  }
13	  return value.trim();
14	}
