28	export function requirePositiveInt(payload: Record<string, unknown>, field: string): number {
29	  const value = payload[field];
30	  if (typeof value !== "number" || !Number.isInteger(value) || value <= 0) {
31	    throw new ValidationError(`entier positif attendu : ${field}`);
